import{_ as t,o as a,c as n,a3 as i}from"./chunks/framework.BlfGB29P.js";const _=JSON.parse('{"title":"设计与实践","description":"建立单 Agent 模式选择方法，并通过只读工具型 Agent 整合本模块能力。","frontmatter":{"title":"设计与实践","description":"建立单 Agent 模式选择方法，并通过只读工具型 Agent 整合本模块能力。"},"headers":[],"relativePath":"py-agent/agent/design-practice/index.md","filePath":"py-agent/agent/design-practice/index.md","lastUpdated":1785314595000}'),l={name:"py-agent/agent/design-practice/index.md"};function o(r,e,d,c,s,p){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="设计与实践" tabindex="-1">设计与实践 <a class="header-anchor" href="#设计与实践" aria-label="Permalink to &quot;设计与实践&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>本分组不再增加零散 API，而是回答两个综合问题：怎样按控制权选择 Agent 模式，以及怎样把模型、工具、Context、Middleware 和结构化结果组合成一个可验收应用。</p><h2 id="_1-学习目标" tabindex="-1">1. 学习目标 <a class="header-anchor" href="#_1-学习目标" aria-label="Permalink to &quot;1. 学习目标&quot;">​</a></h2><p>完成后，你应该能够：</p><ol><li>按“谁决定下一步”比较单 Agent 模式；</li><li>从直接调用和固定工作流基线判断复杂模式是否必要；</li><li>为工具型 Agent 划分模型控制权与应用控制权；</li><li>实现只读订单支持 Agent；</li><li>分层测试领域规则、工具契约和 Agent 行为。</li></ol><h2 id="_2-文章顺序" tabindex="-1">2. 文章顺序 <a class="header-anchor" href="#_2-文章顺序" aria-label="Permalink to &quot;2. 文章顺序&quot;">​</a></h2><ol><li><a href="/py-agent/agent/design-practice/agent-design-patterns">Agent 设计模式</a>：比较工具循环、路由、计划执行、审查修订和混合工作流。</li><li><a href="/py-agent/agent/design-practice/tool-agent-project">项目：工具型 Agent</a>：完成一个带身份 Context、工具授权和结构化输出的项目。</li></ol><h2 id="_3-分组边界" tabindex="-1">3. 分组边界 <a class="header-anchor" href="#_3-分组边界" aria-label="Permalink to &quot;3. 分组边界&quot;">​</a></h2><p>项目刻意限制为单 Agent 和只读工具。写操作、多 Agent 编排、RAG、长期记忆和完整生产部署分别在后续模块扩展。</p>',10)])])}const h=t(l,[["render",o]]);export{_ as __pageData,h as default};
